#pragma once
// Axell Signature Dojo - dry-voice reference for the low-mid balance measure of VoiceAnalysis.h (docs/DESIGN.md, D9).
//
// For every frequency on a 1/12-octave grid from 150 Hz: the mean and the spread (standard deviation, floored at
// 0.5 dB) over 27 dry studio voices (VCTK, CC BY 4.0; CMU ARCTIC) of the voiced long-term spectrum at 1/3-octave
// resolution against its own 2-octave trend. Generated by tools/VoiceLab.cpp (reference) - do not edit by hand.
namespace dojo::voice::reference
{
constexpr int kBoxPoints = 40;               // 150 Hz * 2^(i/12), i = 0..39 (150 Hz .. 1.42 kHz)
constexpr float kSearchLo = 250.0f, kSearchHi = 900.0f;
constexpr float kOutsideZ = 3.0f;            // leave-one-out: 1 of 27 dry voices reaches it (2.5: 3 of 27)

struct Box
{
    float hz[kBoxPoints];
    float mean[kBoxPoints];
    float sd[kBoxPoints];
};

namespace detail
{
constexpr Box neutral()
{
    Box b {};
    double f = 150.0;
    for (int i = 0; i < kBoxPoints; ++i)
    {
        b.hz[i] = (float) f;
        b.mean[i] = 0.0f;
        b.sd[i] = 1.0f;
        f *= 1.0594630943592953;   // 2^(1/12)
    }
    return b;
}
} // namespace detail

// a reference that measures the raw curve (calibration)
inline constexpr Box kNeutral = detail::neutral();

#include "VoiceReferenceData.inc"   // inline constexpr Box kBox = { ... };
} // namespace dojo::voice::reference
